\begin{align*}
    &\generr(\cA, \cD, n) := \e_{\rS \sim \cD^n\hspace{-0.2em},\hspace{0.1em} \rr}\left[\ind\{\cA(\rS,\rr) \notin \supp(\cD) \setminus \rS\}\right] = \p_{\rS\sim \cD^n\hspace{-0.2em},\hspace{0.1em} \rr}[\cA(\rS, \rr) \not\in \supp(\cD)\setminus \rS].
\end{align*}

More formally, recall that we assume the universe of strings $U$ to be a countable set; that is, we can enumerate all the strings in $U$ as $ U=\{u_{1},u_{2},\ldots\} $.
For any language $L\subseteq U$, write
\begin{align*}
    L=\{u_{k_1(L)},u_{k_2(L)},\ldots\},
    \qquad
    k_1(L)<k_2(L)<\cdots,
\end{align*}
for the enumeration of $L$ induced by the enumeration of $U$. Then, for any distribution $ \cD $ over $ U $ and any countable collection of languages $ \cC=\left\{  L_{1}, L_{2},\ldots\right\}  $, where each $L_i \subseteq U $, we define the quantity $i(\cC,\cD)$ as
\begin{align}
    \label{eqn:i-C-D}
        i(\cC,\cD) &:= \min\left\{i \in \bN ~\middle|~ \forall L \in \cC \text{ s.t. } L \nsubseteq \supp(\cD): \exists
        j \le i \text{ s.t. } u_{k_j(L)} \notin \supp(\cD)\right\}.
\end{align}
Here, we define the $\min$ over an empty set to be $\infty$.

